/**
 * Who is using the widget, and what they're allowed to do.
 *
 * Roles come from System Design Doc #1037 (Investor Relations Portal Migration),
 * "Users & Permissions": two Investor Admins with full tranche create/lock/document
 * rights, one Investor Coordinator with tranche-creation and reporting access. The doc
 * also restricts swaps to Josh and Danielle specifically.
 *
 * Identity is resolved from ZOHO.CRM.CONFIG.getCurrentUser() — the real logged-in CRM
 * user. The "View as" control layers on top of that for demos and for checking what
 * each person will actually see; it never grants anything the real user couldn't do
 * server-side, because CRM enforces its own permissions on every API call regardless
 * of what this file says.
 */

export const CAPS = {
  VIEW: 'view',            // see pools, price deals, see economics
  BUILD: 'build',          // add/remove deals, create a draft tranche
  LOCK: 'lock',            // lock a tranche + fire documents
  SWAP: 'swap',            // swap deals in/out of a locked tranche
  PRICING: 'pricing',      // edit the investor pricing matrix
  REPORT: 'report',        // reporting surfaces
};

export const ROLES = {
  investor_admin: {
    key: 'investor_admin',
    label: 'Investor Admin',
    blurb: 'Full tranche rights — create, lock, generate documents, swap',
    caps: [CAPS.VIEW, CAPS.BUILD, CAPS.LOCK, CAPS.SWAP, CAPS.PRICING, CAPS.REPORT],
  },
  investor_coordinator: {
    key: 'investor_coordinator',
    label: 'Investor Coordinator',
    blurb: 'Build tranches and run reports — cannot lock, swap, or change pricing',
    caps: [CAPS.VIEW, CAPS.BUILD, CAPS.REPORT],
  },
  observer: {
    key: 'observer',
    label: 'Observer',
    blurb: 'Read-only — not a named Investor Relations user',
    caps: [CAPS.VIEW],
  },
};

/**
 * Named users from Doc #1037.
 *
 * Matching is by NAME, and by the local part of the email derived from that name
 * (firstlast@…), because the CRM email convention is firstnamelastname@. We deliberately
 * do not hardcode address literals — this bundle is fetched publicly by the browser, and
 * a real address list is the one thing here worth not publishing.
 *
 * UNVERIFIED against real CRM user records. Anyone unmatched falls through to
 * `observer`, which is the safe direction.
 */
export const NAMED_USERS = [
  { name: 'Josh Haney', role: 'investor_admin' },
  // Danielle's real address is drocovitz@, NOT daniellerocovitz@ — the firstnamelastname
  // convention does not hold for her, and without this alias she silently fell through to
  // Observer and lost lock/swap rights.
  { name: 'Danielle Rocovitz', role: 'investor_admin', aliases: ['drocovitz'] },
  { name: 'Makayla McGraw', role: 'investor_coordinator', aliases: ['mmcgraw'] },
];

const norm = (s) => String(s ?? '').trim().toLowerCase();
/** "Josh Haney" → "joshhaney" — the CRM local-part convention. */
const slug = (s) => norm(s).replace(/[^a-z]/g, '');

/** Match a CRM user record to a configured role. */
export function roleForUser(user) {
  if (!user) return ROLES.observer;
  const full = norm(user.full_name || `${user.first_name ?? ''} ${user.last_name ?? ''}`);
  const localPart = slug(String(user.email ?? '').split('@')[0]);

  const hit =
    NAMED_USERS.find((u) => norm(u.name) === full) ||
    (localPart &&
      NAMED_USERS.find(
        (u) => slug(u.name) === localPart || (u.aliases ?? []).some((a) => slug(a) === localPart)
      ));

  return hit ? ROLES[hit.role] : ROLES.observer;
}

export const can = (role, cap) => !!role && role.caps.includes(cap);

/**
 * Why an action is unavailable — so the UI can say "Makayla can't lock" rather than
 * just greying a button out. Gabe's whole complaint about the old process was that
 * people worked around rules they didn't understand.
 */
export function denyReason(role, cap) {
  if (can(role, cap)) return null;
  const what = {
    [CAPS.LOCK]: 'lock tranches or generate documents',
    [CAPS.SWAP]: 'swap deals in or out',
    [CAPS.PRICING]: 'edit investor pricing',
    [CAPS.BUILD]: 'build tranches',
    [CAPS.REPORT]: 'view reporting',
  }[cap] ?? cap;
  return `${role.label} cannot ${what}`;
}

/** Everyone selectable in the "View as" control: the named three plus a plain observer. */
export function viewAsOptions() {
  return [
    ...NAMED_USERS.map((u) => ({
      id: slug(u.name),
      name: u.name,
      role: ROLES[u.role],
    })),
    { id: '__observer__', name: 'Unassigned user', role: ROLES.observer },
  ];
}
